                    exec_id,
                    coverage,
                    needed.len()
                );
            }
            _ => {
                // No executor can cover any remaining partitions
                return Err(Error::MissingPartitions(needed));
            }
        }
    }

    tracing::debug!(
        "Selected {} executor(s) to cover {} partition(s)",
        selected.len(),
        required_partitions.len()
    );

    Ok(selected)
}

